def format_oneline_trace(scope):
    segments = []
    scope = scope.maps[0]
    while LAST_CHILD_SCOPE in scope:
        child = scope[LAST_CHILD_SCOPE]
        segments.append(scope[Spec].__class__.__name__)

        # Get the path information
        if hasattr(scope[Spec], '__ops__'):
            # Handle TType objects
            ops = scope[Spec].__ops__
            if len(ops) > 1:
                path_parts = []
                i = 1
                while i < len(ops):
                    op, arg = ops[i], ops[i + 1]
                    if op == '.':
                        path_parts.append(arg)
                    elif op == '[':
                        path_parts.append(f"[{arg}]")
                    elif op == 'P':
                        path_parts.append(str(arg))
                    elif op == '(':
                        path_parts.append(f"({arg})")
                    i += 2
                segments.append('.'.join(path_parts))

        # Move to parent scope
        scope = child.maps[0]
    else:
        # Add final scope
        segments.append(scope[Spec].__class__.__name__)

    # Build the path representation
    result_parts = []
    for i, segment in enumerate(segments):
        if i == 0:
            result_parts.append(segment)
        else:
            result_parts.append(f"/{segment}")

    return ''.join(result_parts)
